INSERT INTO users (email, password_hash, name, role, status, author_slug, author_title, author_bio) VALUES ('editorial@bamamotors.com', '!disabled', 'BamaMotors Editorial Team', 'admin', 'active', 'bamamotors-editorial-team', 'Editorial Team', 'The BamaMotors editorial team writes and maintains our car buying, financing and ownership guides for Alabama drivers. We research title, registration, tax and consumer-protection topics from official sources such as the Alabama Department of Revenue, the FTC and NHTSA, cite those sources in our articles, and review guides regularly so they stay current. Dealers cannot pay for editorial coverage.');
